entries[132117] = { ["name"] = "Aschegrauer Pandarenphönix", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren purpurroter Pandarenphönix und gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Sowohl der Name als auch die Farbe dieses majestätischen Phönix sollen die Wiedergeburt symbolisieren.\"\nVerkäufer:\nWeltverkäufer\nKosten:\n1" }
entries[132118] = { ["name"] = "Smaragdgrüner Pandarenphönix", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren smaragdgrünen Pandarenphönix und gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Die Gefiederfarben dieses seltenen Phönix sollen großes Glück bringen.\"\nVerkäufer:\nWeltverkäufer\nKosten:\n1" }
entries[132119] = { ["name"] = "Violetter Pandarenphönix", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren violetten Pandarenphönix und gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Das Gefieder des violetten Phönix soll die Vereinigung gegensätzlicher Kräfte symbolisieren.\"\nVerkäufer:\nWeltverkäufer\nKosten:\n1" }
